edit_integration:
PROMPT_SCHEMA:
{
  "role": "object_integration",
  "objective": "Photorealistic integration of reference object into scene",
  "context": "NOT copy-paste - requires professional compositing with relighting",
  "inputs": {
    "image_1": {
      "type": "reference",
      "extract": [
        "shape",
        "structure"
      ],
      "ignore": [
        "lighting",
        "colors",
        "background"
      ]
    },
    "image_2": {
      "type": "target_scene",
      "analyze": [
        "light_direction",
        "color_temperature",
        "shadow_hardness",
        "ambient_light"
      ]
    }
  },
  "integration_steps": {
    "relighting": [
      "apply_scene_light_direction",
      "match_color_temperature",
      "create_matching_shadows",
      "add_ambient_occlusion"
    ],
    "color_grading": [
      "match_scene_palette",
      "match_saturation",
      "match_exposure"
    ],
    "shadows": [
      "cast_onto_surfaces",
      "match_direction",
      "match_softness",
      "add_contact_shadows"
    ],
